//! ↩️ delete-node leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfNode;
use crate::artifacts::gltf::schema::mutations::delete_node::mutation::{validate, GltfDeleteNodePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{nodes_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-node.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteNodeInverseOperation { Insert { position: usize, item: GltfNode }, Delete { index: usize, removed: GltfNode }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteNodeInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteNodePayload, pub operation: GltfDeleteNodeInverseOperation }
fn operation(payload: &GltfDeleteNodePayload, base: &GltfSnapshot) -> GltfDeleteNodeInverseOperation { GltfDeleteNodeInverseOperation::Insert { position: payload.index, item: base.document.nodes[payload.index].clone() } }
fn touched_paths(payload: &GltfDeleteNodePayload) -> Vec<String> { vec![format!("document/nodes/{}", payload.index)] }
pub fn validate_inverse(inverse: &GltfDeleteNodeInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfDeleteNodeInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfDeleteNodeInverseOperation::Insert { position, .. } if *position > after.document.nodes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/nodes", "position must be within the collection")), GltfDeleteNodeInverseOperation::Delete { index, .. } if *index >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "index must address an item")), GltfDeleteNodeInverseOperation::Move { index, position } if *index >= after.document.nodes.len() || *position >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "indices must address items")), GltfDeleteNodeInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.nodes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.nodes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/nodes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfDeleteNodeInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Nodes, &Change::Insert(*position))?; next.document.nodes.insert(*position, item.clone());  }, GltfDeleteNodeInverseOperation::Delete { index, .. } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, None, None)?;  }, GltfDeleteNodeInverseOperation::Move { index, position } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, Some(*position), None)?;  }, GltfDeleteNodeInverseOperation::Reorder { order } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfDeleteNodeInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfDeleteNodePayload, base: &GltfSnapshot) -> Result<GltfDeleteNodeInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteNodeInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
